//! The compiler's stack limit (design §5.6), after `Zend/zend_call_stack.c`
//! and the check `zend_compile.c` makes under `ZEND_CHECK_STACK_LIMIT`:
//! the compiler recurses on the tree, one native frame per node, and a
//! tree deep enough would take the thread down with it. php reads two
//! ini entries, `zend.max_allowed_stack_size` and
//! `zend.reserved_stack_size`, works a limit address out of them once
//! per thread (`zend_call_stack_init`), and compares a local's address to
//! it at the top of `zend_compile_expr`, `zend_compile_var`,
//! `zend_delayed_compile_var` and `zend_eval_const_expr`; past the limit
//! it raises `E_COMPILE_ERROR` with php's sentence, and the request ends
//! there instead of in a signal. What is here is that pair of addresses
//! and that comparison; the engine builds one per request, on the
//! request's thread, and hands it to the compiler in
//! [`crate::Options`].
//!
//! The thread's own bounds are php's reading too. `zend_call_stack_get`
//! asks the platform for the calling thread's base and size, and this
//! crate forbids `unsafe`, so the asking is `php_heap`'s,
//! [`php_heap::call_stack_bounds`], read through `heap.lock`; the
//! native stack is the host's thread's, whatever size the host gave it,
//! and the engine sizes no thread of its own (design §5.6, §5.14). A
//! thread the platform cannot describe gets php's own fallback, the
//! `ZEND_MAX_ALLOWED_STACK_SIZE_DETECT` arm of `zend_call_stack_init`
//! where `base` is null: the address of a local at init as the base,
//! which "is not the actual stack base", and the size php assumes for
//! the platform, [`php_heap::call_stack_default_size`], less 32 KiB for
//! the distance already walked; the limit is then an estimate, as php's
//! is there. A host thread smaller than a program needs is not refused
//! at `serve`: the limit is what the thread has, and a nesting past it
//! is the same fatal php raises on the same thread, earlier.

use php_heap::{call_stack_bounds, call_stack_default_size, main_call_stack_size};
use php_unit::Level;

use crate::{CompileError, Refused};

/// `EG(stack_base)` and `EG(stack_limit)`, the two addresses
/// `zend_call_stack_init` leaves for the thread: the limit zero where
/// nothing is checked, which is what `zend.max_allowed_stack_size=-1`
/// asks for.
///
/// Beside them the floor: the thread's own end with the same reserve
/// above it, which is where the limit stands under detect. php checks
/// the limit before the walks it guards, `execute_ex`'s entry, the
/// compiler, the object comparison, `var_dump()`'s properties,
/// `serialize()`, `http_build_query()` and `json_encode()`; this engine
/// holds every other walk to the floor ([`exhausted`](Self::exhausted)),
/// so a nesting php takes whole under a small limit is taken whole here
/// too and one deeper than the thread is an `Error`.
///
/// Under detect the limit is php's own, worked out of the size php's
/// main thread has ([`php_heap::main_call_stack_size`]), where the
/// thread a host serves on is larger: a request is served on a stack
/// sized for the loop's own re-entry, whose level costs a multiple of
/// php's (design §5.6, #3043), and a native's own recursion, which
/// costs about what php's C costs, would otherwise go that multiple
/// deeper than php before it is refused (#3142, ruled on #3158). The
/// loop's entry is held to the floor instead
/// ([`entry_overflowed`](Self::entry_overflowed)),
/// and at each native's call back into PHP the limit moves to php's
/// budget below the frame that called ([`reentered`](Self::reentered)),
/// so the stack a callback recursion took above it is not charged to a
/// native's recursion below it at the loop's price.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub struct StackLimit {
    base: usize,
    limit: usize,
    floor: usize,
    allowed: Allowed,
}

/// How the limit stands: where [`StackLimit::init`] or
/// [`StackLimit::fiber`] put it, or php's budget measured down from the
/// frame that last entered the loop from a native.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
enum Allowed {
    /// A size `zend.max_allowed_stack_size` gave, `-1` among them: the
    /// loop's entry is held to the limit too.
    #[default]
    Fixed,
    /// A fiber's stack, its limit at its floor: held as
    /// [`Allowed::Fixed`] is, and no scope of the loop is nested on it
    /// ([`StackLimit::nested`]), since no limit below one can move.
    Fiber,
    /// Detect: `span` bytes below the base, or below the frame a
    /// re-entry stands at, never past the floor; the loop's entry is
    /// held to the floor. `span` is the main thread's size, or the
    /// thread's own where that is smaller, less
    /// `zend.reserved_stack_size`: the number php's sentence names.
    Detected { span: usize },
}

/// Where [`StackLimit::reentered`] or [`StackLimit::nested`] found the
/// limit, which [`StackLimit::left`] puts back once the serving or the
/// scope it began is over.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[must_use = "the limit a re-entry moved is put back when it is over"]
pub struct Reentered(Option<usize>);

/// `ZEND_MAX_ALLOWED_STACK_SIZE_DETECT`, the entry's default.
const DETECT: i64 = 0;

/// The least `zend.reserved_stack_size` php takes, the two arms of
/// `OnUpdateReservedStackSize` (`Z/Zend/zend.c:212-216`): room for one
/// `alloca`, PCRE2's start frames and a few plain calls below the check
/// where `ZEND_ALLOCA_MAX_SIZE` is defined, and `32*1024` where it is
/// not. `Z/Zend/zend_portability.h:219` defines it only where
/// `!defined(__APPLE__)`, so php on macOS reserves 32K and php on
/// Linux and the BSDs 48K, and the number the stack-limit fatal prints
/// differs by 16K between them; `ini_get` answers `0` on both.
#[cfg(target_vendor = "apple")]
const RESERVED_MIN: u64 = 32 * 1024;
/// `ZEND_ALLOCA_MAX_SIZE + 16*1024`, the arm above where the `alloca`
/// macro is compiled (`Z/Zend/zend_portability.h:219`).
#[cfg(not(target_vendor = "apple"))]
const RESERVED_MIN: u64 = 32 * 1024 + 16 * 1024;

impl StackLimit {
    /// The `ZEND_MAX_ALLOWED_STACK_SIZE_UNCHECKED` arm: no base and no
    /// limit, so [`check`](Self::check) never refuses. What
    /// [`crate::Options::default`] carries, since a caller that says
    /// nothing of its thread has told the compiler nothing to hold it to.
    pub const UNCHECKED: StackLimit = StackLimit {
        base: 0,
        limit: 0,
        floor: 0,
        allowed: Allowed::Fixed,
    };

    /// `zend_call_stack_init` on the calling thread, from the two ini
    /// entries as the engine parsed them: `max_allowed` is
    /// `zend.max_allowed_stack_size`, `-1` unchecked, `0` detect and a
    /// positive number the size to allow from here; `reserved` is
    /// `zend.reserved_stack_size`, `0` for php's minimum, which a smaller
    /// number is raised to as php's `OnUpdate` handler refuses it.
    ///
    /// Detect reads the thread's bounds as the platform describes them,
    /// `php_heap::call_stack_bounds`; on a thread it cannot describe,
    /// the base is where this frame stands and the size is
    /// `php_heap::call_stack_default_size` less the 32 KiB php allows
    /// for the frames already below the real base. Where the thread is
    /// larger than the process's main thread, detect allows what the
    /// main thread has, php's budget, and the rest of the thread is the
    /// loop's entry's ([`Allowed::Detected`]). A positive number is the
    /// size to allow below the base the platform read, or below this
    /// frame where it read none. Where the main thread's size cannot be
    /// read, under `ulimit -s unlimited` on Linux among them, php's
    /// main thread falls back to the size php assumes
    /// ([`php_heap::call_stack_default_size`]), and so does the budget.
    #[must_use]
    pub fn init(max_allowed: i64, reserved: u64) -> StackLimit {
        let reserved = reserved.max(RESERVED_MIN);
        let reserved = usize::try_from(reserved).unwrap_or(usize::MAX);
        let read = call_stack_bounds();
        let base = read.map_or_else(position, |stack| stack.base);
        let thread = read.map_or_else(
            || call_stack_default_size().saturating_sub(32 * 1024),
            |stack| stack.max_size,
        );
        let floor = limit(base, thread, reserved);
        let (limit, allowed) = match max_allowed {
            DETECT => {
                let main = main_call_stack_size().unwrap_or_else(call_stack_default_size);
                let php = read.map_or(thread, |_| main.min(thread));
                let limit = limit(base, php, reserved).max(floor);
                let span = base.saturating_sub(limit);
                (limit, Allowed::Detected { span })
            }
            allowed if allowed > 0 => {
                let size = usize::try_from(allowed).unwrap_or(usize::MAX);
                (limit(base, size, reserved), Allowed::Fixed)
            }
            _ => (0, Allowed::Fixed),
        };
        StackLimit {
            base,
            limit,
            floor,
            allowed,
        }
    }

    /// The limit inside a fiber, which `zend_fiber_execute` writes over
    /// the thread's before the fiber's body runs
    /// (`Z/Zend/zend_fibers.c:590-593`): the base is the high address
    /// of the stack the engine laid down for the fiber,
    /// `zend_fiber_stack_base`, and the limit its lowest usable address
    /// plus `zend.reserved_stack_size`, `zend_fiber_stack_limit`
    /// (`:337-359`), the reserve doubled on Apple for
    /// `___chkstk_darwin`, which reads twice as far below an alternative
    /// stack. Neither is read off the thread, and
    /// `zend.max_allowed_stack_size` is not
    /// asked: php says in as many words that the maximum for a fiber is
    /// `fiber.stack_size` (`Z/Zend/zend.c:276`), so a recursion inside
    /// one is refused at the fiber's depth (design §5.11).
    #[must_use]
    pub fn fiber(base: usize, end: usize, reserved: u64) -> StackLimit {
        let reserved = usize::try_from(reserved.max(RESERVED_MIN)).unwrap_or(usize::MAX);
        let reserved = if cfg!(target_vendor = "apple") {
            reserved.saturating_mul(2)
        } else {
            reserved
        };
        let limit = end.saturating_add(reserved);
        StackLimit {
            base,
            limit,
            floor: limit,
            allowed: Allowed::Fiber,
        }
    }

    /// A native calling back into PHP, `zend_call_function`, or a
    /// generator resumed, from the calling frame: under detect the limit
    /// moves to php's budget below this frame, never past the floor, so
    /// a native's own recursion inside the callback has what php's has
    /// there whatever the loop's re-entries above it took; otherwise it
    /// stands. What it was is handed back for [`left`](Self::left).
    ///
    /// A recursion that alternates between a native and its callback,
    /// `serialize()` calling `__serialize` calling `serialize()`, meets
    /// php's budget afresh below each re-entry, so it is refused only at
    /// the floor, where php refuses it at a depth of 5,000: the engine
    /// never refuses a recursion php serves, and this difference is a
    /// by-design divergence (design §5.6, #3158).
    ///
    /// ```php
    /// class S { function __construct(public $n) {} function __serialize(): array { return $this->n ? [serialize(new S($this->n - 1))] : []; } }
    /// try { echo strlen(serialize(new S(5000))), "\n"; } catch (Error $e) { echo $e->getMessage(), "\n"; }
    /// ```
    /// ```expect capture
    /// Maximum call stack size of 8339456 bytes (zend.max_allowed_stack_size - zend.reserved_stack_size) reached. Infinite recursion?
    /// ```
    #[inline]
    pub fn reentered(&mut self) -> Reentered {
        let Allowed::Detected { span } = self.allowed else {
            return Reentered(None);
        };
        let held = self.limit;
        self.limit = position().saturating_sub(span).max(self.floor);
        Reentered(Some(held))
    }

    /// A frame php enters in the same `execute_ex`, an `eval`'s or an
    /// included file's (`INCLUDE_OR_EVAL`'s `ZEND_VM_ENTER`), served by
    /// the caller on `charge` bytes of the thread of its own. php's
    /// `eval` takes none of the machine stack, so the limit moves
    /// `charge` bytes down, never past the floor, and php's budget below
    /// the frame is what it was above it. The limit moves so whether its
    /// size was given or detected. What it was is handed back for
    /// [`left`](Self::left). None where the thread has less than `charge`
    /// and `room` above its floor, or no known end, and on a fiber's
    /// stack, whose limit is its floor ([`fiber`](Self::fiber)), so a
    /// scope there would spend the fiber's own budget, which php's
    /// `eval` leaves whole (#3192): the caller serves the frame without
    /// moving it. With no limit there is none to move.
    #[inline]
    pub fn nested(&mut self, charge: usize, room: usize) -> Option<Reentered> {
        // A thread whose end is not known, the limit not worked out yet,
        // has no room to measure.
        if self.allowed == Allowed::Fiber
            || self.floor == 0
            || position() <= self.floor.saturating_add(charge).saturating_add(room)
        {
            return None;
        }
        let held = self.limit;
        if held != 0 {
            self.limit = held.saturating_sub(charge).max(self.floor);
        }
        Some(Reentered(Some(held)))
    }

    /// The serving [`reentered`](Self::reentered) or the scope
    /// [`nested`](Self::nested) began is over: the limit stands where it
    /// stood before it.
    #[inline]
    pub fn left(&mut self, reentered: Reentered) {
        if let Reentered(Some(limit)) = reentered {
            self.limit = limit;
        }
    }

    /// `zend_check_stack_limit`: nothing while the calling frame stands
    /// above the limit, and past it php's `E_COMPILE_ERROR`
    /// (`zend_stack_limit_error`), whose number is the distance from the
    /// base to the limit, `zend.max_allowed_stack_size` less
    /// `zend.reserved_stack_size` as the message says.
    ///
    /// A left-nested chain is one node deeper per link and no deeper
    /// for the parser, so php's grammar takes it whole and php's
    /// compiler refuses it here, at about fifty thousand links under an
    /// 8 MiB stack, where twenty thousand nested parentheses are the
    /// parser's `memory exhausted`. The number is the thread's size less
    /// [`RESERVED_MIN`]: the recipe runs `php -n`, so the size is
    /// detected, read from the platform by both engines and so the
    /// rlimit's under the shell that runs them, and a fence carries no
    /// ini entry to fix it, so the witness masks the number; the
    /// sentence, the file and the line are pinned, and the engine's own
    /// test pins the number under `zend.max_allowed_stack_size=512K`.
    /// Two hundred thousand links is #246's measurement, room for a
    /// stack four times the default.
    ///
    /// ```php
    /// $y = ;
    /// echo 'never';
    /// ```
    /// ```expect exit=255
    /// Fatal error: Maximum call stack size of %d bytes (zend.max_allowed_stack_size - zend.reserved_stack_size) reached during compilation. Try splitting expression in %s on line 2
    /// ```
    ///
    /// Under the small-stack regime the stack is the ini's 256K, which a
    /// chain a quarter of the size above passes in both engines, built
    /// at runtime and compiled by `eval`; the number is still masked,
    /// since the least `zend.reserved_stack_size` it is taken from is the
    /// platform's ([`RESERVED_MIN`]).
    ///
    /// ```php
    /// eval('$y = 1' . str_repeat('+1', 50000) . ';');
    /// echo 'never';
    /// ```
    /// ```expect regime=small-stack exit=255
    /// Fatal error: Maximum call stack size of %d bytes (zend.max_allowed_stack_size - zend.reserved_stack_size) reached during compilation. Try splitting expression in %s(2) : eval()'d code on line 1
    /// ```
    pub(crate) fn check(&self, line: u32) -> Result<(), CompileError> {
        if !self.overflowed() {
            return Ok(());
        }
        let max_stack_size = self.max_stack_size();
        Err(Refused {
            level: Level::CompileError,
            message: format!(
                "Maximum call stack size of {max_stack_size} bytes (zend.max_allowed_stack_size - zend.reserved_stack_size) reached during compilation. Try splitting expression"
            ).into(),
            line,
            raised: Vec::new(),
            raise: crate::Raise::Fatal,
            stage: crate::Stage::Compiling,
            declared: None,
            keys_made: 0,
        }.into())
    }
}

impl StackLimit {
    /// `zend_call_stack_overflowed(EG(stack_limit))`: whether the
    /// calling thread has come down to the limit. What
    /// [`check`](Self::check) asks before it refuses a compilation and
    /// what `zend_objects_check_stack_limit` asks before it compares
    /// two objects, which is the engine's to ask and to word, since the
    /// text is that site's. [`UNCHECKED`](Self::UNCHECKED) has no
    /// limit, so it never answers true.
    #[must_use]
    pub fn overflowed(&self) -> bool {
        position() <= self.limit
    }

    /// `execute_ex`'s own `zend_call_stack_overflowed(EG(stack_limit))`
    /// at its entry, the loop's re-entry from a native: the limit where
    /// a size was given, and under detect the floor, the whole of the
    /// thread the host sized for the loop's re-entry (design §5.6).
    #[must_use]
    pub fn entry_overflowed(&self) -> bool {
        let at = match self.allowed {
            Allowed::Fixed | Allowed::Fiber => self.limit,
            Allowed::Detected { .. } => self.floor,
        };
        position() <= at
    }

    /// `EG(stack_limit)` itself: the address a frame at or below has
    /// [`overflowed`](Self::overflowed), zero where nothing is checked.
    #[must_use]
    pub fn limit(&self) -> usize {
        self.limit
    }

    /// The size `zend_call_stack_size_error` names, the stack's base less
    /// its limit: `zend.max_allowed_stack_size` less
    /// `zend.reserved_stack_size`, and under detect php's main thread's
    /// size less the reservation, wherever the limit stands and whichever
    /// limit refused.
    #[must_use]
    pub fn max_stack_size(&self) -> usize {
        match self.allowed {
            Allowed::Fixed | Allowed::Fiber => self.base.saturating_sub(self.limit),
            Allowed::Detected { span } => span,
        }
    }

    /// Whether the calling thread has come down to the floor, what a
    /// walk php does not guard asks at each level. Under detect the
    /// floor is the limit, so this is [`overflowed`](Self::overflowed);
    /// under a smaller `zend.max_allowed_stack_size` it is deeper, and
    /// under `-1` it is still the thread's end.
    /// [`UNCHECKED`](Self::UNCHECKED) has no floor.
    #[must_use]
    pub fn exhausted(&self) -> bool {
        position() <= self.floor
    }

    /// Whether a walk php guards at the limit refuses its next level
    /// here: past the limit, as [`overflowed`](Self::overflowed) asks,
    /// or past the floor where no limit is set or the floor stands above
    /// it, as [`exhausted`](Self::exhausted) asks, since this engine
    /// never runs a walk to the thread's end. `var_dump()`'s rows ask it.
    #[must_use]
    pub fn refuses_a_level(&self) -> bool {
        self.overflowed() || self.exhausted()
    }

    /// The stack's base less its floor, the size a walk held to the
    /// floor had when it was refused, in the words of
    /// [`max_stack_size`](Self::max_stack_size).
    #[must_use]
    pub fn floor_size(&self) -> usize {
        self.base.saturating_sub(self.floor)
    }
}

/// `zend_call_stack_limit`: the address `size` bytes below `base` and
/// `reserved` above that, zero where the size is more than the address
/// itself and the top of memory where the reservation would wrap.
fn limit(base: usize, size: usize, reserved: usize) -> usize {
    if size > base {
        return 0;
    }
    let base = base - size;
    if usize::MAX - base < reserved {
        return usize::MAX;
    }
    base + reserved
}

/// `zend_call_stack_position`: the address of a local of the calling
/// frame, php's `__builtin_frame_address(0)`. Stacks grow down, so a
/// deeper frame is a smaller address.
#[inline]
fn position() -> usize {
    let here = 0u8;
    std::ptr::addr_of!(here).addr()
}

#[cfg(test)]
#[allow(
    clippy::disallowed_methods,
    reason = "a test starts its own threads (seams.toml rule fork.threads)"
)]
mod tests {
    use super::*;

    /// A limit that allows nothing beyond the reservation refuses the
    /// next frame down, with php's number in php's sentence.
    #[test]
    fn a_limit_at_the_base_refuses_the_next_frame() {
        let stack = StackLimit::init(1, 0);
        let refused = deeper(&stack).err();
        assert_eq!(refused.as_ref().map(|e| e.level), Some(Level::CompileError));
        assert_eq!(refused.as_ref().map(|e| e.line), Some(2));
        // `limit` clamps a size smaller than the reservation to the
        // reservation above the base less one.
        assert!(
            refused.is_some_and(|e| e.message.starts_with("Maximum call stack size of ")
                && e.message.ends_with(
                    " bytes (zend.max_allowed_stack_size - zend.reserved_stack_size) reached during compilation. Try splitting expression"
                )),
        );
    }

    /// `-1` is unchecked, and so is a default `Options`; the floor of
    /// `-1` is still the thread's, what detect's limit is.
    #[test]
    fn minus_one_is_unchecked() {
        let minus_one = StackLimit::init(-1, 0);
        assert_eq!(minus_one.limit, 0);
        assert!(!minus_one.overflowed());
        assert!(deeper(&minus_one).is_ok());
        assert_eq!(minus_one.floor, StackLimit::init(0, 0).floor);
        assert!(deeper(&StackLimit::UNCHECKED).is_ok());
        assert!(!StackLimit::UNCHECKED.exhausted());
        assert_eq!(crate::Options::default().stack, StackLimit::UNCHECKED);
    }

    /// A limit smaller than the thread leaves the floor at the thread's
    /// end: a walk held to the floor goes on past the limit, and under
    /// detect the two are one address.
    #[test]
    fn the_floor_is_the_threads_end_whatever_the_limit() {
        let small = StackLimit::init(256 * 1024, 0);
        let detect = StackLimit::init(0, 0);
        assert_eq!(detect.floor, detect.limit);
        assert_eq!(small.floor, detect.floor);
        assert!(small.floor < small.limit);
        assert!(!small.exhausted());
        assert_eq!(small.floor_size(), detect.max_stack_size());
    }

    /// Detect on a test thread leaves room for a frame, and a size a
    /// frame fits in does too: the size php prints is the size allowed
    /// less the reservation.
    #[test]
    fn the_number_is_the_size_less_the_reservation() {
        let stack = StackLimit::init(1024 * 1024, 0);
        assert!(deeper(&stack).is_ok());
        assert_eq!(
            stack.base - stack.limit,
            1024 * 1024 - usize::try_from(RESERVED_MIN).unwrap_or(0)
        );
        let reserved = StackLimit::init(1024 * 1024, 100 * 1024);
        assert_eq!(reserved.base - reserved.limit, 924 * 1024);
        assert!(deeper(&StackLimit::init(0, 0)).is_ok());
    }

    /// Detect reads the thread the limit is built on: on a thread
    /// spawned at one size, the number is that size less the
    /// reservation, to the page, and the base is above every local of
    /// the thread. On a platform this engine has no arm for, the
    /// fallback's number is the assumed size less php's 32 KiB.
    ///
    /// The size is above the 2 MiB the test harness spawns each test
    /// on: glibc keeps a finished thread's stack in a cache and hands
    /// it to the next thread that asks for one no larger, and
    /// `pthread_getattr_np` then answers the cached stack's size, so a
    /// thread asked for 1 MiB read as 2 MiB on the CI machine now and
    /// then (`nptl/allocatestack.c`, `get_cached_stack`). A size no
    /// cached stack reaches is served fresh, at the size asked for.
    #[test]
    fn detect_reads_the_calling_threads_bounds() {
        let size = 4 * 1024 * 1024;
        let (stack, local) = std::thread::Builder::new()
            .stack_size(size)
            .spawn(|| {
                let stack = StackLimit::init(0, 0);
                (stack, position())
            })
            .expect("a thread of the size asked")
            .join()
            .expect("the thread runs to its end");
        let reserved = usize::try_from(RESERVED_MIN).unwrap_or(0);
        let read = stack.base - stack.limit + reserved;
        if php_heap::call_stack_bounds().is_some() {
            assert!(
                read >= size && read < 2 * size,
                "a {size}-byte thread reads as {read}"
            );
            assert!(local < stack.base && local > stack.limit);
        } else {
            assert_eq!(read, php_heap::call_stack_default_size() - 32 * 1024);
        }
    }

    /// A fiber's limit is its own stack's: the reservation above the
    /// lowest address, doubled on Apple, and php's least where the entry
    /// asks for less.
    #[test]
    fn a_fibers_limit_is_its_stacks_end_and_the_reserve() {
        let doubled = if cfg!(target_vendor = "apple") { 2 } else { 1 };
        let reserved = usize::try_from(RESERVED_MIN).unwrap_or(0) * doubled;
        let stack = StackLimit::fiber(0x20_0000, 0x10_0000, 0);
        assert_eq!(stack.base, 0x20_0000);
        assert_eq!(stack.limit, 0x10_0000 + reserved);
        let wider = StackLimit::fiber(0x20_0000, 0x10_0000, 64 * 1024);
        assert_eq!(wider.limit, 0x10_0000 + 64 * 1024 * doubled);
    }

    /// On a fiber's stack no scope nests, however much of the stack is
    /// left (#3192): its limit is its floor, so a scope's frames would
    /// be the fiber's budget. Off a fiber the same stack nests one.
    #[test]
    fn a_fibers_stack_nests_no_scope() {
        let here = position();
        let mut fiber = StackLimit::fiber(here + 1024, here - 4 * 1024 * 1024, 0);
        let limit = fiber.limit;
        assert_eq!(fiber.nested(4096, 4096), None);
        assert_eq!(fiber.limit, limit);
        let mut fixed = StackLimit {
            allowed: Allowed::Fixed,
            ..fiber
        };
        assert!(fixed.nested(4096, 4096).is_some());
    }

    /// `Zend/tests/generators/bug71441.phpt`'s sum, two thousand `+`
    /// deep, and the same sum as a constant's initialiser, compile under
    /// detect on a thread of the shell's default 8 MiB in the
    /// unoptimised build the tests and the phpt lane use, which lays each
    /// frame's locals side by side; php's own compile spends less than a
    /// tenth of that per nesting. The guard on the frame the compiler
    /// spends per nesting (#1434).
    #[test]
    fn a_two_thousand_term_sum_compiles_on_an_eight_mib_thread() {
        let sums = [
            format!("<?php\n$a = 1;\n$y = $a + {} $a;", "1 +".repeat(2000)),
            format!("<?php\nconst Y = 1{};", " + 1".repeat(2000)),
        ];
        let refused = std::thread::Builder::new()
            .stack_size(8 * 1024 * 1024)
            .spawn(move || {
                let options = crate::Options {
                    stack: StackLimit::init(0, 0),
                    ..crate::Options::default()
                };
                let mut strings = php_heap::Strings::new();
                sums.iter()
                    .map(|source| {
                        crate::compile_source(
                            &mut php_syntax::Arena::new(),
                            source.as_bytes(),
                            &options,
                            &mut strings,
                        )
                        .err()
                        .map(|refused| refused.message.to_string())
                    })
                    .collect::<Vec<_>>()
            })
            .expect("a thread of 8 MiB")
            .join()
            .expect("the thread runs to its end");
        assert_eq!(refused, vec![None, None]);
    }

    /// `limit`'s two clamps.
    #[test]
    fn a_size_past_the_address_and_a_reservation_past_memory_clamp() {
        assert_eq!(limit(100, 200, 10), 0);
        assert_eq!(limit(usize::MAX - 10, 5, 100), usize::MAX);
        assert_eq!(limit(1000, 200, 50), 850);
    }

    /// On a thread larger than the process's main thread, detect holds
    /// a native's recursion to the main thread's size and the loop's
    /// entry to the thread's own, names the main thread's number, and a
    /// re-entry moves the limit to that budget below its frame until it
    /// is left; under a size the ini gave, a re-entry moves nothing. A
    /// platform whose main thread's size cannot be read skips, and fails
    /// where the machine promised the size (#3180).
    #[test]
    fn detect_on_a_thread_past_the_main_threads_size_allows_the_main_threads() {
        match php_heap::main_call_stack_size() {
            Some(main) => detect_past_the_main_thread(main),
            None => crate::skip::skip(
                crate::skip::MAIN_STACK,
                "this platform's main thread has no size to read",
            ),
        }
    }

    /// The test above, on a thread four times `main`, the main thread's
    /// size.
    fn detect_past_the_main_thread(main: usize) {
        let size = main.saturating_mul(4);
        let (at_init, clear, moved, left, local) = std::thread::Builder::new()
            .stack_size(size)
            .spawn(|| {
                let mut stack = StackLimit::init(0, 0);
                let at_init = stack;
                let clear = !stack.overflowed() && !stack.entry_overflowed();
                let reentered = stack.reentered();
                let moved = stack;
                stack.left(reentered);
                (at_init, clear, moved, stack, position())
            })
            .expect("a thread four times the main thread's size")
            .join()
            .expect("the thread runs to its end");
        let reserved = usize::try_from(RESERVED_MIN).expect("the reserve fits an address");
        assert_eq!(at_init.max_stack_size(), main - reserved);
        assert_eq!(at_init.base - at_init.limit, main - reserved);
        assert!(at_init.base - at_init.floor >= size - reserved);
        assert!(clear);
        assert!(moved.limit < at_init.limit && moved.limit > local.saturating_sub(main));
        assert_eq!(moved.max_stack_size(), main - reserved);
        assert_eq!(left, at_init);
        let mut fixed = StackLimit::init(1024 * 1024, 0);
        let before = fixed;
        let reentered = fixed.reentered();
        assert_eq!(fixed, before);
        fixed.left(reentered);
        assert_eq!(fixed, before);
    }

    /// One frame below the caller, which is where the compiler checks.
    #[inline(never)]
    fn deeper(stack: &StackLimit) -> Result<(), CompileError> {
        std::hint::black_box(stack).check(2)
    }
}
